import type { NextFunction, Request, Response } from "express";
import { auth } from "./lib/firebase-admin.js";
import { SubscriptionService } from "../../subscription-service/subscription.service.js";
import { TierInfo, SubscriptionTier } from "../../../shared/subscription-types.js";

const ADMIN_EMAIL = process.env.ADMIN_EMAIL || "abdoullahaljersi@gmail.com";

export type AuthUser = {
  sub: string;
  email?: string;
  uid: string;
};

declare global {
  namespace Express {
    interface Request {
      authUser?: AuthUser;
      isAdmin?: boolean;
      userTier?: TierInfo;
      subscription?: TierInfo;
    }
  }
}

async function parseBearerToken(req: Request): Promise<string | null> {
  const header = req.headers.authorization;
  if (!header) return null;
  const [scheme, token] = header.split(" ");
  if (scheme?.toLowerCase() !== "bearer" || !token) return null;
  return token;
}

export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const token = await parseBearerToken(req);
    if (!token) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const decodedToken = await auth.verifyIdToken(token);

    req.authUser = {
      sub: decodedToken.uid,
      email: decodedToken.email,
      uid: decodedToken.uid,
    };
    req.isAdmin = (decodedToken.email ?? "").toLowerCase() === ADMIN_EMAIL.toLowerCase();

    next();
  } catch (error) {
    console.error("Auth Error:", error);
    res.status(401).json({ error: "Unauthorized" });
  }
}

export async function optionalAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const token = await parseBearerToken(req);
    if (!token) {
      next();
      return;
    }

    const decodedToken = await auth.verifyIdToken(token);

    req.authUser = {
      sub: decodedToken.uid,
      email: decodedToken.email,
      uid: decodedToken.uid,
    };
    req.isAdmin = (decodedToken.email ?? "").toLowerCase() === ADMIN_EMAIL.toLowerCase();

    next();
  } catch (_err) {
    // If token is invalid, just proceed as guest
    next();
  }
}

export async function requireAdmin(req: Request, res: Response, next: NextFunction) {
  await requireAuth(req, res, () => {
    if (!req.isAdmin) {
      res.status(403).json({ error: "Forbidden" });
      return;
    }
    next();
  });
}

/**
 * Middleware to attach user's tier information to request
 * Does not block access - just adds tier info
 */
export async function optionalTier(req: Request, res: Response, next: NextFunction) {
  if (!req.authUser) {
    next();
    return;
  }

  try {
    const tierInfo = await SubscriptionService.getUserSubscription(req.authUser.sub);
    if (tierInfo) {
      req.userTier = tierInfo;
      req.subscription = tierInfo;
    }
    next();
  } catch (error) {
    // Don't block on tier lookup failure
    console.error('Error fetching tier info:', error);
    next();
  }
}

/**
 * Middleware factory to require minimum tier level
 * Usage: requireTier('core') or requireTier('pro')
 */
export function requireTier(minTier: SubscriptionTier) {
  const tierHierarchy: Record<SubscriptionTier, number> = {
    free: 0,
    core: 1,
    pro: 2,
  };

  return async (req: Request, res: Response, next: NextFunction) => {
    await requireAuth(req, res, async () => {
      try {
        const tierInfo = await SubscriptionService.getUserSubscription(req.authUser!.sub);

        if (!tierInfo) {
          res.status(403).json({
            error: "No active subscription",
            message: "Please subscribe to access this feature",
            requiredTier: minTier
          });
          return;
        }

        req.userTier = tierInfo;
        req.subscription = tierInfo;

        const userTierLevel = tierHierarchy[tierInfo.tier];
        const requiredTierLevel = tierHierarchy[minTier];

        if (userTierLevel < requiredTierLevel) {
          res.status(403).json({
            error: "Insufficient tier",
            message: `This feature requires ${minTier} tier or higher`,
            currentTier: tierInfo.tier,
            requiredTier: minTier
          });
          return;
        }

        next();
      } catch (error: any) {
        res.status(500).json({
          error: "Failed to verify subscription",
          message: error.message
        });
      }
    });
  };
}

/**
 * Middleware to check if user has credits available
 */
export async function requireCredits(req: Request, res: Response, next: NextFunction) {
  await requireAuth(req, res, async () => {
    try {
      const hasCredits = await SubscriptionService.checkCreditsAvailable(req.authUser!.sub);

      if (!hasCredits) {
        const usageStats = await SubscriptionService.getUsageStats(req.authUser!.sub);
        res.status(429).json({
          error: "Credit limit exceeded",
          message: "You've used all your chat credits for this billing period",
          usage: usageStats,
          upgradeUrl: "/pricing"
        });
        return;
      }

      next();
    } catch (error: any) {
      res.status(500).json({
        error: "Failed to check credits",
        message: error.message
      });
    }
  });
}

import * as React from "react";
import {
  User,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signOut as firebaseSignOut,
  onAuthStateChanged,
  updateProfile
} from "firebase/auth";
import { doc, getDoc, setDoc, serverTimestamp } from "firebase/firestore";
import { auth, db } from "@/lib/firebase";

type UserRole = 'user' | 'admin';

type UserProfile = {
  id: string;
  email: string;
  role: UserRole;
  full_name?: string;
  avatar_url?: string;
  created_at: any;
};

type AuthState = {
  user: User | null;
  profile: UserProfile | null;
  isAdmin: boolean;
  loading: boolean;
  signInWithPassword: (params: { email: string; password: string }) => Promise<void>;
  signUp: (params: { email: string; password: string; fullName: string }) => Promise<{ error: Error | null }>;
  signOut: () => Promise<void>;
  refreshProfile: () => Promise<void>;
};

const AuthContext = React.createContext<AuthState | undefined>(undefined);

// Function to get user role from profile
const getUserRole = (profile: UserProfile | null): UserRole => {
  if (!profile) return 'user';
  return profile.role || 'user';
};

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = React.useState<User | null>(null);
  const [profile, setProfile] = React.useState<UserProfile | null>(null);
  const [loading, setLoading] = React.useState(true);

  // Fetch user profile from Firestore
  const fetchUserProfile = React.useCallback(async (userId: string) => {
    try {
      const profileRef = doc(db, 'users', userId);
      const profileSnap = await getDoc(profileRef);

      if (profileSnap.exists()) {
        return profileSnap.data() as UserProfile;
      }
      return null;
    } catch (error) {
      if (import.meta.env.DEV) {
        console.error('Error fetching user profile:', error);
      }
      return null;
    }
  }, []);

  // Listen for auth state changes
  React.useEffect(() => {
    let mounted = true;

    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (!mounted) return;

      setUser(firebaseUser);

      if (firebaseUser) {
        // Fetch profile from Firestore
        const userProfile = await fetchUserProfile(firebaseUser.uid);
        if (mounted) {
          setProfile(userProfile);
        }
      } else {
        setProfile(null);
      }

      if (mounted) {
        setLoading(false);
      }
    });

    // Safety timeout
    const timeout = setTimeout(() => {
      if (mounted) {
        console.warn('Auth loading timeout - setting loading to false');
        setLoading(false);
      }
    }, 5000);

    return () => {
      mounted = false;
      clearTimeout(timeout);
      unsubscribe();
    };
  }, [fetchUserProfile]);

  const signInWithPassword = React.useCallback(async ({ email, password }: { email: string; password: string }) => {
    setLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } finally {
      setLoading(false);
    }
  }, []);

  const signUp = React.useCallback(async ({ email, password, fullName }: { email: string; password: string; fullName: string }) => {
    setLoading(true);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;

      // Update display name
      await updateProfile(user, {
        displayName: fullName
      });

      // Create user profile in Firestore
      const userProfile: UserProfile = {
        id: user.uid,
        email: email,
        full_name: fullName,
        role: 'user',
        created_at: serverTimestamp()
      };

      await setDoc(doc(db, 'users', user.uid), userProfile);

      return { error: null };
    } catch (error) {
      if (import.meta.env.DEV) {
        console.error('Signup error:', error);
      }
      return { error: error as Error };
    } finally {
      setLoading(false);
    }
  }, []);

  const signOut = React.useCallback(async () => {
    // Clear state immediately
    setProfile(null);
    setUser(null);
    setLoading(false);

    // Sign out from Firebase
    try {
      await firebaseSignOut(auth);
    } catch (error) {
      if (import.meta.env.DEV) {
        console.error('Sign out error:', error);
      }
    }
  }, []);

  const refreshProfile = React.useCallback(async () => {
    if (user) {
      try {
        const userProfile = await fetchUserProfile(user.uid);
        setProfile(userProfile);
      } catch (error) {
        if (import.meta.env.DEV) {
          console.error('Error refreshing profile:', error);
        }
      }
    }
  }, [user, fetchUserProfile]);

  const isAdmin = React.useMemo(() => {
    return getUserRole(profile) === 'admin';
  }, [profile]);

  const value = React.useMemo(
    () => ({
      user,
      profile,
      isAdmin,
      loading,
      signInWithPassword,
      signUp,
      signOut,
      refreshProfile,
    }),
    [user, profile, isAdmin, loading, signInWithPassword, signUp, signOut, refreshProfile]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = React.useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { useState, useEffect } from 'react';
import { Button } from '../ui/button';
import { Card } from '../ui/card';
import { Label } from '../ui/label';
import { toast } from 'sonner';
import { Palette, RefreshCw, Sparkles } from 'lucide-react';

interface ThemeColors {
    primary_color: string;
    accent_color: string;
    background_light?: string;
    background_dark?: string;
}

interface ThemeCustomizerProps {
    onThemeChange?: (colors: ThemeColors) => void;
}

export function ThemeCustomizer({ onThemeChange }: ThemeCustomizerProps) {
    const [colors, setColors] = useState<ThemeColors>({
        primary_color: '#8B7355',
        accent_color: '#D4AF37',
        background_light: '#FFFFFF',
        background_dark: '#1A1A1A',
    });
    const [hasAccess, setHasAccess] = useState<boolean | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        checkAccess();
        fetchTheme();
    }, []);

    const checkAccess = async () => {
        try {
            const token = localStorage.getItem('token');
            if (!token) return;

            const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:4000';
            const response = await fetch(`${apiUrl}/api/themes/access`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                },
            });

            const data = await response.json();
            setHasAccess(data.hasAccess);
        } catch (error) {
            console.error('Failed to check theme access:', error);
            setHasAccess(false);
        }
    };

    const fetchTheme = async () => {
        try {
            const token = localStorage.getItem('token');
            if (!token) return;

            const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:4000';
            const response = await fetch(`${apiUrl}/api/themes/me`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                },
            });

            const data = await response.json();
            if (data.success && data.theme) {
                setColors({
                    primary_color: data.theme.primary_color,
                    accent_color: data.theme.accent_color,
                    background_light: data.theme.background_light,
                    background_dark: data.theme.background_dark,
                });
                applyTheme(data.theme);
            }
        } catch (error) {
            console.error('Failed to fetch theme:', error);
        } finally {
            setLoading(false);
        }
    };

    const applyTheme = (theme: any) => {
        const root = document.documentElement;
        root.style.setProperty('--primary', theme.primary_color);
        root.style.setProperty('--accent', theme.accent_color);

        if (onThemeChange) {
            onThemeChange(theme);
        }
    };

    const handleColorChange = (key: keyof ThemeColors, value: string) => {
        const newColors = { ...colors, [key]: value };
        setColors(newColors);
        applyTheme(newColors);
    };

    const saveTheme = async () => {
        if (!hasAccess) {
            toast.error('Upgrade to Core or Pro to customize your theme');
            return;
        }

        setSaving(true);
        try {
            const token = localStorage.getItem('token');
            const response = await fetch('http://localhost:4000/api/themes/me', {
                method: 'PUT',
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(colors),
            });

            const data = await response.json();

            if (data.success) {
                toast.success('Theme saved successfully!');
            } else if (response.status === 403) {
                toast.error(data.message || 'Upgrade required for custom themes');
            } else {
                toast.error(data.message || 'Failed to save theme');
            }
        } catch (error) {
            toast.error('Failed to save theme');
            console.error(error);
        } finally {
            setSaving(false);
        }
    };

    const resetTheme = async () => {
        try {
            const token = localStorage.getItem('token');
            await fetch('http://localhost:4000/api/themes/me', {
                method: 'DELETE',
                headers: {
                    'Authorization': `Bearer ${token}`,
                },
            });

            const defaults = {
                primary_color: '#8B7355',
                accent_color: '#D4AF37',
                background_light: '#FFFFFF',
                background_dark: '#1A1A1A',
            };

            setColors(defaults);
            applyTheme(defaults);
            toast.success('Theme reset to defaults');
        } catch (error) {
            toast.error('Failed to reset theme');
            console.error(error);
        }
    };

    if (loading) {
        return (
            <Card className="p-6">
                <div className="flex items-center justify-center">
                    <RefreshCw className="w-6 h-6 animate-spin text-primary" />
                </div>
            </Card>
        );
    }

    return (
        <Card className="p-6">
            <div className="flex items-center gap-2 mb-6">
                <Palette className="w-5 h-5 text-primary" />
                <h3 className="text-lg font-semibold">Custom Theme Colors</h3>
                {!hasAccess && (
                    <span className="ml-auto text-xs bg-primary/10 text-primary px-2 py-1 rounded-full flex items-center gap-1">
                        <Sparkles className="w-3 h-3" />
                        Core/Pro Only
                    </span>
                )}
            </div>

            {!hasAccess && (
                <div className="mb-4 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
                    <p className="text-sm text-amber-800 dark:text-amber-200">
                        🎨 Upgrade to <strong>Core</strong> or <strong>Pro</strong> to unlock custom theme colors and make the platform truly yours!
                    </p>
                </div>
            )}

            <div className="space-y-4">
                <div>
                    <Label htmlFor="primary-color">Primary Color</Label>
                    <div className="flex gap-2 mt-1">
                        <input
                            id="primary-color"
                            type="color"
                            value={colors.primary_color}
                            onChange={(e) => handleColorChange('primary_color', e.target.value)}
                            className="h-10 w-16 rounded border cursor-pointer disabled:opacity-50"
                            disabled={!hasAccess}
                        />
                        <input
                            type="text"
                            value={colors.primary_color}
                            onChange={(e) => handleColorChange('primary_color', e.target.value)}
                            className="flex-1 px-3 py-2 rounded-lg border border-input bg-background disabled:opacity-50"
                            placeholder="#8B7355"
                            disabled={!hasAccess}
                        />
                    </div>
                </div>

                <div>
                    <Label htmlFor="accent-color">Accent Color</Label>
                    <div className="flex gap-2 mt-1">
                        <input
                            id="accent-color"
                            type="color"
                            value={colors.accent_color}
                            onChange={(e) => handleColorChange('accent_color', e.target.value)}
                            className="h-10 w-16 rounded border cursor-pointer disabled:opacity-50"
                            disabled={!hasAccess}
                        />
                        <input
                            type="text"
                            value={colors.accent_color}
                            onChange={(e) => handleColorChange('accent_color', e.target.value)}
                            className="flex-1 px-3 py-2 rounded-lg border border-input bg-background disabled:opacity-50"
                            placeholder="#D4AF37"
                            disabled={!hasAccess}
                        />
                    </div>
                </div>

                <div className="pt-4 flex gap-2">
                    <Button
                        onClick={saveTheme}
                        disabled={!hasAccess || saving}
                        className="flex-1"
                    >
                        {saving ? (
                            <>
                                <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                                Saving...
                            </>
                        ) : (
                            'Save Theme'
                        )}
                    </Button>
                    <Button
                        onClick={resetTheme}
                        variant="outline"
                        disabled={!hasAccess}
                    >
                        Reset
                    </Button>
                </div>
            </div>

            {hasAccess && (
                <div className="mt-4 p-3 bg-primary/5 rounded-lg">
                    <p className="text-xs text-muted-foreground">
                        💡 <strong>Pro tip:</strong> Changes are previewed live. Click "Save Theme" to persist your customizations.
                    </p>
                </div>
            )}
        </Card>
    );
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  )
}

export { Badge, badgeVariants }

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline:
          "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        islamicPrimary:
          "bg-islamic-green text-white hover:bg-islamic-green/90 shadow-md",
        islamicOutline:
          "bg-background text-primary border border-primary hover:border-primary/80",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-md px-3",
        lg: "h-11 rounded-md px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
  VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button"
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }

import * as React from "react"
import { type DialogProps } from "@radix-ui/react-dialog"
import { Command as CommandPrimitive } from "cmdk"
import { Search } from "lucide-react"

import { cn } from "@/lib/utils"
import { Dialog, DialogContent } from "@/components/ui/dialog"

const Command = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive>
>(({ className, ...props }, ref) => (
  <CommandPrimitive
    ref={ref}
    className={cn(
      "flex h-full w-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground",
      className
    )}
    {...props}
  />
))
Command.displayName = CommandPrimitive.displayName

interface CommandDialogProps extends React.ComponentPropsWithoutRef<typeof Dialog> { }

const CommandDialog = ({ children, ...props }: CommandDialogProps) => {
  return (
    <Dialog {...props}>
      <DialogContent className="overflow-hidden p-0 shadow-lg">
        <Command className="[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0 [&_[cmdk-group]]:px-2 [&_[cmdk-input-wrapper]_svg]:h-5 [&_[cmdk-input-wrapper]_svg]:w-5 [&_[cmdk-input]]:h-12 [&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-3 [&_[cmdk-item]_svg]:h-5 [&_[cmdk-item]_svg]:w-5">
          {children}
        </Command>
      </DialogContent>
    </Dialog>
  )
}

const CommandInput = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Input>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Input>
>(({ className, ...props }, ref) => (
  <div className="flex items-center border-b px-3" cmdk-input-wrapper="">
    <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
    <CommandPrimitive.Input
      ref={ref}
      className={cn(
        "flex h-11 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    />
  </div>
))

CommandInput.displayName = CommandPrimitive.Input.displayName

const CommandList = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.List>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.List>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.List
    ref={ref}
    className={cn("max-h-[300px] overflow-y-auto overflow-x-hidden", className)}
    {...props}
  />
))

CommandList.displayName = CommandPrimitive.List.displayName

const CommandEmpty = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Empty>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Empty>
>((props, ref) => (
  <CommandPrimitive.Empty
    ref={ref}
    className="py-6 text-center text-sm"
    {...props}
  />
))

