            const newAgents = { ...agents, [agentId]: updatedAgent };

            // Save to localStorage
            localStorage.setItem('admin_agents_config', JSON.stringify(newAgents));
            setAgents(newAgents);

            toast({
                title: "Saved!",
                description: `${updatedAgent.agentName} configuration updated.`
            });
        } catch (error) {
            toast({
                title: "Save Failed",
                description: "Could not save configuration.",
                variant: "destructive"
            });
        } finally {
            setSaving(false);
        }
    };

    const updateLLMField = (agentId: string, field: string, value: string | number) => {
        setAgents(prev => ({
            ...prev,
            [agentId]: {
                ...prev[agentId],
                llmConfig: {
                    ...prev[agentId].llmConfig,
                    [field]: value
                }
            }
        }));
    };

    const testModel = async (agentId: string) => {
        setTesting(agentId);
        try {
            const agent = agents[agentId];
            if (!agent) throw new Error('Agent not found');

            const testMessage = `You are ${agent.agentName}. Respond with "Hello, I am ${agent.agentName} and I am working correctly."`;

            const response = await openRouter.generateCompletion([
                {
                    role: 'system',
                    content: `You are ${agent.agentName}, ${COUNCIL_MODELS_CONFIG.find(m => m.memberId === agentId)?.role || 'a council member'}.`
                },
                {
                    role: 'user',
                    content: testMessage
                }
            ], {
                model: agent.llmConfig.model,
                temperature: agent.llmConfig.temperature,
                maxTokens: 100
            });

            if (response && response.length > 0) {
                setTestResults(prev => ({
                    ...prev,
                    [agentId]: {
                        success: true,
                        message: 'Model is working correctly!'
                    }
                }));
                toast({
                    title: "Test Successful",
                    description: `${agent.agentName} is responding correctly.`
                });
            } else {
                throw new Error('Empty response');
            }
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : 'Unknown error';
            setTestResults(prev => ({
                ...prev,
                [agentId]: {
                    success: false,
                    message: errorMessage || 'Test failed'
                }
            }));
            toast({
                title: "Test Failed",
                description: errorMessage || 'Could not test model',
                variant: "destructive"
            });
        } finally {
            setTesting(null);
        }
    };

    const testAllModels = async () => {
        for (const agentId of Object.keys(agents)) {
            await testModel(agentId);
            // Small delay between tests
            await new Promise(resolve => setTimeout(resolve, 500));
        }
    };

    if (loading) {
        return (
            <div className="flex-1 min-h-screen flex items-center justify-center">
                <div className="text-center">
                    <RefreshCw className="w-8 h-8 text-primary animate-spin mx-auto mb-4" />
                    <p className="text-islamic-dark/70">Loading configuration...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="flex-1 min-h-screen bg-gradient-to-br from-islamic-cream/30 via-white to-islamic-gold/10">
            <section className="container py-10 md:py-16">
                <header className="mb-12">
                    <p className="inline-flex items-center text-xs uppercase tracking-[0.22em] text-islamic-dark/60 mb-3">
                        <span className="w-1.5 h-1.5 rounded-full bg-islamic-gold mr-2" />
                        Admin Panel
                    </p>
                    <h1 className="text-4xl md:text-5xl font-bold text-islamic-dark mb-4">
                        <span className="text-gradient">Model Configuration</span>
                    </h1>
                    <p className="text-islamic-dark/70 max-w-2xl leading-relaxed">
                        Assign LLMs to each epistemic agent and configure their parameters.
                    </p>
                </header>

                {/* OpenRouter Status Check */}
                <div className="mb-6 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
                    <div className="flex items-center justify-between">
                        <div>
                            <h3 className="font-semibold text-islamic-dark mb-1">OpenRouter API Status</h3>
                            <p className="text-xs text-primary dark:text-primary-foreground mt-1 font-medium">
                                💰 All recommended models are FREE on OpenRouter!
                            </p>
                        </div>
                        <Button
                            onClick={testAllModels}
                            disabled={testing !== null || !import.meta.env.VITE_OPENROUTER_API_KEY}
                            className="btn-islamic"
                        >
                            <TestTube className="w-4 h-4 mr-2" />
                            Test All Models
                        </Button>
                    </div>
                </div>

                <div className="max-w-5xl mx-auto space-y-6">
                    {Object.entries(agents).map(([agentId, agent]) => {
                        const modelConfig = COUNCIL_MODELS_CONFIG.find(m => m.memberId === agentId);
                        const isRecommended = modelConfig && agent.llmConfig.model === modelConfig.modelId;
                        const testResult = testResults[agentId];

                        return (
                            <div key={agentId} className="islamic-card p-6 bg-card/95">
                                <div className="flex items-center justify-between mb-6">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                                            <Settings className="w-5 h-5 text-primary" />
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-2">
                                                <h3 className="font-semibold text-islamic-dark">{agent.agentName}</h3>
                                                {isRecommended && (
                                                    <Badge className="bg-primary text-primary-foreground">Recommended</Badge>
                                                )}
                                                {testResult && (
                                                    testResult.success ? (
                                                        <CheckCircle className="w-5 h-5 text-primary" />
                                                    ) : (
                                                        <XCircle className="w-5 h-5 text-red-500" />
                                                    )
                                                )}
                                            </div>
                                            <p className="text-xs text-islamic-dark/60">
                                                {modelConfig?.role || 'Agent ID: ' + agentId}
                                            </p>
                                            {modelConfig && (
                                                <p className="text-xs text-islamic-dark/50 mt-1">
                                                    {modelConfig.description}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <Button
                                            onClick={() => testModel(agentId)}
                                            disabled={testing === agentId || !import.meta.env.VITE_OPENROUTER_API_KEY}
                                            variant="outline"
                                            size="sm"
                                        >
                                            {testing === agentId ? (
                                                <>
                                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                                    Testing...
                                                </>
                                            ) : (
                                                <>
                                                    <TestTube className="w-4 h-4 mr-2" />
                                                    Test
                                                </>
                                            )}
                                        </Button>
                                        <button
                                            onClick={() => updateAgent(agentId, agent)}
                                            disabled={saving}
                                            className="btn-islamic-outlined flex items-center gap-2"
                                        >
                                            <Save className="w-4 h-4" />
                                            Save
                                        </button>
                                    </div>
                                </div>

                                {testResult && (
                                    <div className={`mb-4 p-3 rounded-lg ${testResult.success ? 'bg-primary/10 dark:bg-primary/20' : 'bg-red-50 dark:bg-red-900/20'}`}>
                                        <p className={`text-sm ${testResult.success ? 'text-primary dark:text-primary-foreground' : 'text-red-700 dark:text-red-300'}`}>
                                            {testResult.message}
                                        </p>
                                    </div>
                                )}

                                {modelConfig && agent.llmConfig.model !== modelConfig.modelId && (
                                    <div className="mb-4 p-3 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800">
                                        <p className="text-sm text-yellow-700 dark:text-yellow-300">
                                            💡 Recommended model: <strong>{modelConfig.recommendedModel}</strong> ({modelConfig.modelId})
                                        </p>
                                        <Button
                                            onClick={() => {
                                                updateLLMField(agentId, 'model', modelConfig.modelId);
                                                updateLLMField(agentId, 'temperature', modelConfig.temperature);
                                                updateLLMField(agentId, 'maxTokens', modelConfig.maxTokens);
                                            }}
                                            variant="outline"
                                            size="sm"
                                            className="mt-2"
                                        >
                                            Use Recommended Model
                                        </Button>
                                    </div>
                                )}

                                <div className="grid md:grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-islamic-dark mb-2">
                                            Provider
                                        </label>
                                        <select
                                            value={agent.llmConfig.provider}
                                            onChange={(e) => updateLLMField(agentId, 'provider', e.target.value)}
                                            className="w-full px-4 py-2 rounded-lg border border-input bg-background/50 text-foreground focus:ring-2 focus:ring-primary/40"
                                        >
                                            {availableModels.map((p) => (
                                                <option key={p.provider} value={p.provider}>
                                                    {p.provider.charAt(0).toUpperCase() + p.provider.slice(1)}
                                                </option>
                                            ))}
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-islamic-dark mb-2">
                                            Model
                                        </label>
                                        <select
                                            value={agent.llmConfig.model}
                                            onChange={(e) => updateLLMField(agentId, 'model', e.target.value)}
                                            className="w-full px-4 py-2 rounded-lg border border-input bg-background/50 text-foreground focus:ring-2 focus:ring-primary/40"
                                        >
                                            {availableModels
                                                .find(p => p.provider === agent.llmConfig.provider)
                                                ?.models.map((model) => (
                                                    <option key={model} value={model}>{model}</option>
                                                ))}
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-islamic-dark mb-2">
                                            Temperature
                                        </label>
                                        <input
                                            type="number"
                                            step="0.1"
                                            min="0"
                                            max="2"
                                            value={agent.llmConfig.temperature}
                                            onChange={(e) => updateLLMField(agentId, 'temperature', parseFloat(e.target.value))}
                                            className="w-full px-4 py-2 rounded-lg border border-input bg-background/50 text-foreground focus:ring-2 focus:ring-primary/40"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-islamic-dark mb-2">
                                            Max Tokens
                                        </label>
                                        <input
                                            type="number"
                                            step="100"
                                            value={agent.llmConfig.maxTokens}
                                            onChange={(e) => updateLLMField(agentId, 'maxTokens', parseInt(e.target.value))}
                                            className="w-full px-4 py-2 rounded-lg border border-input bg-background/50 text-foreground focus:ring-2 focus:ring-primary/40"
                                        />
                                    </div>

                                    <div className="md:col-span-2">
                                        <label className="block text-sm font-medium text-islamic-dark mb-2">
                                            API Key (Uses VITE_OPENROUTER_API_KEY from .env)
                                        </label>
                                        <input
                                            type="text"
                                            placeholder="Uses environment variable (VITE_OPENROUTER_API_KEY)"
                                            value={import.meta.env.VITE_OPENROUTER_API_KEY ? '••••••••••••' : 'Not configured'}
                                            disabled
                                            className="w-full px-4 py-2 rounded-lg border border-islamic-cream bg-gray-100 text-islamic-dark/60 cursor-not-allowed"
                                        />
                                        <p className="text-xs text-islamic-dark/50 mt-1">
                                            All models use the same OpenRouter API key from your .env file
                                        </p>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div >

                {/* Synthesis Model Info */}
                < div className="mt-8 p-6 bg-purple-50 dark:bg-purple-900/20 rounded-lg border border-purple-200 dark:border-purple-800" >
                    <h3 className="font-semibold text-islamic-dark mb-2">Epistemic Synthesis Engine</h3>
                    <p className="text-sm text-islamic-dark/70 mb-2">
                        The synthesis engine combines all council member responses into a final answer.
                    </p>
                    <div className="flex items-center gap-4 text-sm">
                        <div>
                            <span className="font-medium">Recommended Model:</span> {SYNTHESIS_MODEL.name}
                        </div>
                        <div>
                            <span className="font-medium">Model ID:</span> {SYNTHESIS_MODEL.modelId}
                        </div>
                        <div>
                            <span className="font-medium">Temperature:</span> {SYNTHESIS_MODEL.temperature}
                        </div>
                    </div>
                    <p className="text-xs text-islamic-dark/50 mt-2">
                        {SYNTHESIS_MODEL.description}
                    </p>
                </div >
            </section >
        </div >
    );
};

export default AdminConfig;

import * as React from "react";
import { Upload, FileText, Trash2, CheckCircle, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useLanguage } from "@/contexts/LanguageContext";
import { storage } from "@/lib/firebase"; // Firebase Storage
import { ref, uploadBytes, getDownloadURL, listAll, deleteObject } from "firebase/storage";
import { openRouter } from "@/lib/openrouter";

interface DocumentMetadata {
    id: string;
    filename: string;
    category: string;
    uploadedAt: string;
    status: 'uploaded' | 'processing' | 'ready' | 'error';
    chunkCount?: number;
    url?: string;
}

const AGENT_CATEGORIES = [
    { value: 'agent-fiqh', label: 'Fiqh Reasoning Agent' },
    { value: 'agent-aqeedah', label: 'Aqeedah Boundary Agent' },
    { value: 'agent-humility', label: 'Humility & Abstention Agent' },
    { value: 'agent-context', label: 'Contemporary Context Agent' },
    { value: 'general', label: 'General (All Agents)' }
];

const DocumentUpload: React.FC = () => {
    const { t } = useLanguage();
    const [documents, setDocuments] = React.useState<DocumentMetadata[]>([]);
    const [uploading, setUploading] = React.useState(false);
    const [openingId, setOpeningId] = React.useState<string | null>(null);
    const [selectedAgent, setSelectedAgent] = React.useState(AGENT_CATEGORIES[0].value);
    const [dragActive, setDragActive] = React.useState(false);
    const fileInputRef = React.useRef<HTMLInputElement>(null);
    const { toast } = useToast();

    React.useEffect(() => {
        loadDocuments();
    }, [selectedAgent]); // Reload when agent changes to see relevant files

    const loadDocuments = async () => {
        try {
            // List files from Firebase Storage
            const listRef = ref(storage, selectedAgent); // Use simplified path strategy: agent-name/filename
            // Note: Firebase Storage listing is flat by default or via prefix.
            // If we organize by folders (prefixes), we list items in that prefix.
            // If folder doesn't exist yet, it returns empty list (which is fine).

            const res = await listAll(listRef);

            const documentsList: DocumentMetadata[] = await Promise.all(res.items.map(async (itemRef) => {
                // Get metadata if possible, for now just filename and url
                const url = await getDownloadURL(itemRef);
                return {
                    id: itemRef.fullPath,
                    filename: itemRef.name,
                    category: selectedAgent,
                    uploadedAt: new Date().toISOString(), // Storage list doesn't give date easily without getMetadata
                    status: 'ready' as const,
                    url: url
                };
            }));

            // If we want detailed metadata (created_at), we need getMetadata call per item.
            // For performance, we skip it or could implement a separate database index.

            setDocuments(documentsList);
        } catch (error) {
            // If error is "object-not-found" (folder empty), just set empty
            console.error('Error loading documents:', error);
            setDocuments([]); // Default to empty
        }
    };

    const handleOpen = async (doc: DocumentMetadata) => {
        if (doc.url) {
            window.open(doc.url, '_blank', 'noopener,noreferrer');
            return;
        }

        // Fallback if URL missed
        setOpeningId(doc.id);
        try {
            const itemRef = ref(storage, doc.id);
            const url = await getDownloadURL(itemRef);
            window.open(url, '_blank', 'noopener,noreferrer');
        } catch (error: any) {
            toast({
                title: 'Open Failed',
                description: error.message || 'Could not open document',
                variant: 'destructive'
            });
        } finally {
            setOpeningId(null);
        }
    };

    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);

        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            handleFileUpload(e.dataTransfer.files[0]);
        }
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            handleFileUpload(e.target.files[0]);
        }
    };

    const [uploadProgress, setUploadProgress] = React.useState(0);

    const handleFileUpload = async (file: File) => {
        if (!file.name.match(/\.(txt|pdf|docx|md)$/i)) {
            toast({
                title: "Invalid File Type",
                description: "Please upload a TXT, PDF, DOCX, or MD file.",
                variant: "destructive"
            });
            return;
        }

        setUploading(true);
        setUploadProgress(0);

        try {
            // Upload to Firebase Storage
            const fileName = `${Date.now()}_${file.name}`;
            const filePath = `${selectedAgent}/${fileName}`;
            const storageRef = ref(storage, filePath);

            // Use resumable upload for progress
            const uploadTask = import('firebase/storage').then(({ uploadBytesResumable }) => {
                const task = uploadBytesResumable(storageRef, file);

                return new Promise<void>((resolve, reject) => {
                    task.on('state_changed',
                        (snapshot) => {
                            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
                            setUploadProgress(progress);
                        },
                        (error) => {
                            reject(error);
                        },
                        async () => {
                            // Upload completed successfully
                            resolve();
                        }
                    );
                });
            });

            await uploadTask;

            // Process document for RAG if it's a text file
            if (file.name.match(/\.(txt|md)$/i)) {
                const text = await file.text();

                // Use OpenRouter to generate embeddings/chunks (simplified - in production use proper RAG service)
                try {
                    await openRouter.generateCompletion([
                        {
                            role: 'system',
                            content: 'You are a document processor. Extract key information from this Islamic document for RAG indexing.'
                        },
                        {
                            role: 'user',
                            content: `Process this document for RAG:\n\n${text.substring(0, 3000)}`
                        }
                    ], {
                        model: 'openai/gpt-4o-mini',
                        maxTokens: 500
                    });
                } catch (ragError) {
                    console.warn('RAG processing failed, document uploaded but not indexed:', ragError);
                }
            }

            toast({
                title: "Upload Success",
                description: `${file.name} uploaded successfully!`
            });
            loadDocuments();
        } catch (error: any) {
            console.error('Upload error:', error);
            toast({
                title: t('error.upload_failed'),
                description: error.message || t('error.upload_failed'),
                variant: "destructive"
            });
        } finally {
            setUploading(false);
            setUploadProgress(0);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    const handleDelete = async (id: string, filename: string) => {
        try {
            const itemRef = ref(storage, id);
            await deleteObject(itemRef);

            toast({
                title: "Deleted",
                description: "Document removed successfully."
            });
            loadDocuments();
        } catch (error: any) {
            toast({
                title: "Delete Failed",
                description: error.message || t('error.delete_failed'),
                variant: "destructive"
            });
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'ready':
                return <CheckCircle className="w-4 h-4 text-islamic-green-600" />;
            case 'processing':
            case 'uploaded':
                return <Loader2 className="w-4 h-4 text-islamic-gold animate-spin" />;
            case 'error':
                return <span className="text-red-500">❌</span>;
            default:
                return null;
        }
    };

    return (
        <div className="flex-1 min-h-screen bg-gradient-to-br from-islamic-cream/30 via-[#efefec] to-islamic-gold/10">
            <section className="container py-10 md:py-16">
                <header className="mb-12">
                    <p className="inline-flex items-center text-xs uppercase tracking-[0.22em] text-islamic-dark/60 mb-3">
                        <span className="w-1.5 h-1.5 rounded-full bg-islamic-gold mr-2" />
                        RAG Knowledge Base
                    </p>
                    <h1 className="text-4xl md:text-5xl font-bold text-islamic-dark mb-4">
                        <span className="text-gradient">Document Upload</span>
                    </h1>
                    <p className="text-islamic-dark/70 max-w-2xl leading-relaxed">
                        Upload documents to train the epistemic agents. Each document is processed and indexed for retrieval.
                    </p>
                </header>

                <div className="max-w-4xl mx-auto space-y-8">
                    {/* Upload Area */}
                    <div className="islamic-card p-8 bg-[#efefec]/95">
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-islamic-dark mb-3">
                                Select Agent (Documents tagged for specific agent)
                            </label>
                            <select
                                value={selectedAgent}
                                onChange={(e) => setSelectedAgent(e.target.value)}
                                className="w-full px-4 py-3 rounded-lg border border-islamic-cream bg-[#efefec] text-islamic-dark focus:ring-2 focus:ring-islamic-gold/40"
                            >
                                {AGENT_CATEGORIES.map(cat => (
                                    <option key={cat.value} value={cat.value}>{cat.label}</option>
                                ))}
                            </select>
                        </div>

                        <div
                            className={`border-2 border-dashed rounded-2xl p-12 text-center transition-colors ${dragActive
                                ? 'border-islamic-gold bg-islamic-gold/10'
                                : 'border-islamic-cream hover:border-islamic-gold/50'
                                }`}
                            onDragEnter={handleDrag}
                            onDragLeave={handleDrag}
                            onDragOver={handleDrag}
                            onDrop={handleDrop}
                        >
                            <input
                                ref={fileInputRef}
                                type="file"
                                onChange={handleFileSelect}
                                accept=".txt,.pdf,.docx,.md"
                                className="hidden"
                            />

                            <Upload className="w-12 h-12 text-islamic-gold mx-auto mb-4" />
                            <p className="text-lg font-semibold text-islamic-dark mb-2">
                                Drag and drop your document here
                            </p>
                            <p className="text-sm text-islamic-dark/60 mb-4">
                                or click to browse (PDF, TXT, DOCX, MD)
                            </p>

                            <button
                                onClick={() => fileInputRef.current?.click()}
                                disabled={uploading}
                                className="btn-islamic disabled:opacity-50"
                            >
                                {uploading ? (
                                    <div className="w-full flex flex-col items-center gap-2">
                                        <div className="w-full h-2 bg-islamic-cream rounded-full overflow-hidden">
                                            <div
                                                className="h-full bg-islamic-gold transition-all duration-300 ease-out"
                                                style={{ width: `${uploadProgress}%` }}
                                            />
                                        </div>
                                        <span className="text-xs text-islamic-dark/60">
                                            Uploading... {Math.round(uploadProgress)}%
                                        </span>
                                    </div>
                                ) : 'Select File'}
                            </button>
                        </div>
                    </div>

                    {/* Document List */}
                    <div className="islamic-card p-6 bg-[#efefec]/95">
                        <h3 className="text-xl font-bold text-islamic-dark mb-4 flex items-center gap-2">
                            <FileText className="w-5 h-5" />
                            Uploaded Documents
                        </h3>

                        {documents.length === 0 ? (
                            <p className="text-sm text-islamic-dark/60 text-center py-8">
                                No documents uploaded yet.
                            </p>
                        ) : (
                            <div className="space-y-3">
                                {documents.map((doc) => (
                                    <div key={doc.id} className="flex items-center justify-between p-4 rounded-lg border border-islamic-cream hover:bg-islamic-cream/30 transition-colors">
                                        <div className="flex items-center gap-3 flex-1">
                                            {getStatusIcon(doc.status)}
                                            <div className="flex-1">
                                                <p className="font-medium text-islamic-dark">{doc.filename}</p>
                                                <p className="text-xs text-islamic-dark/60">
                                                    {AGENT_CATEGORIES.find(c => c.value === doc.category)?.label || doc.category} •
                                                    {doc.chunkCount ? ` ${doc.chunkCount} chunks` : ` ${doc.status}`}
                                                </p>
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2">
                                            <button
                                                onClick={() => handleOpen(doc)}
                                                disabled={openingId === doc.id}
                                                className="px-3 py-2 text-xs rounded-lg border border-islamic-cream text-islamic-dark/80 hover:text-islamic-dark hover:border-islamic-gold/50 transition-colors disabled:opacity-50"
                                                title="Preview / Download"
                                            >
                                                {openingId === doc.id ? 'Opening...' : 'Open'}
                                            </button>

                                            <button
                                                onClick={() => handleDelete(doc.id, doc.filename)}
                                                className="p-2 text-islamic-dark/40 hover:text-red-500 rounded-lg transition-colors"
                                                title={t('error.delete_document')}
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </section>
        </div>
    );
};

export default DocumentUpload;

import React, { useEffect, useState } from 'react';
import { EcosystemService } from '@/services/ecosystem';
import { MediaContent } from '@/types/ecosystem';
import { Button } from '@/components/ui/button';
import { PlayCircle, Clock } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { useLanguage } from '@/contexts/LanguageContext';
import { MOCK_VIDEOS } from '@/lib/mock-data';

export default function MediaPage() {
    const { t } = useLanguage();
    const [videos, setVideos] = useState<MediaContent[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('all');

    useEffect(() => {
        loadVideos();
    }, [activeTab]);

    const loadVideos = async () => {
        setLoading(true);
        const audience = activeTab === 'all' ? undefined : activeTab;
        const filteredVideos = activeTab === 'all' 
            ? MOCK_VIDEOS 
            : MOCK_VIDEOS.filter(v => v.audience === activeTab);
        
        // Use mock data immediately and stop loading
        setVideos(filteredVideos);
        setLoading(false);
        
        // Try to fetch from API in background (fire and forget)
        (async () => {
            try {
                const data = await EcosystemService.getVideos(audience);
                if (data.length > 0) {
                    setVideos(data);
                }
            } catch (error) {
                // Silently fail, already using mock data
            }
        })();
    };

    const handleWatch = (video: MediaContent) => {
        toast.info(`Starting video: ${video.title}`);
        // In a real app, this would open a video player modal or navigate to /watch/:id
        // For MVP, we'll simulate progress
        EcosystemService.updateVideoProgress(video.id, 60, video.duration_seconds || 120);
    };

    return (
        <div className="flex-1">
            <section className="container py-10 md:py-16 space-y-10">
                <header className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                    <div>
                        <p className="inline-flex items-center text-xs uppercase tracking-[0.22em] text-islamic-dark/60 dark:text-slate-400 mb-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-islamic-gold mr-2" />
                            {t('media.title')}
                        </p>
                        <h1 className="text-3xl md:text-4xl font-bold text-islamic-dark dark:text-slate-100">
                            {t('media.subtitle')}
                        </h1>
                        <p className="mt-2 text-islamic-dark/70 dark:text-slate-300 max-w-xl">
                            {t('media.intro')}
                        </p>
                    </div>
                </header>

            <div className="w-full mb-8">
                <div className="flex flex-wrap gap-3">
                    <button
                        onClick={() => setActiveTab('all')}
                        className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-200 ${
                            activeTab === 'all'
                                ? 'bg-islamic-green-600 text-white shadow-md hover:bg-islamic-green-700'
                                : 'bg-[#efefec] dark:bg-slate-800 text-islamic-dark dark:text-slate-300 border border-islamic-dark/20 dark:border-slate-700 hover:border-islamic-green-600 dark:hover:border-islamic-green hover:text-islamic-green-600 dark:hover:text-islamic-green'
                        }`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setActiveTab('kids')}
                        className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-200 ${
                            activeTab === 'kids'
                                ? 'bg-islamic-green-600 text-white shadow-md hover:bg-islamic-green-700'
                                : 'bg-[#efefec] dark:bg-slate-800 text-islamic-dark dark:text-slate-300 border border-islamic-dark/20 dark:border-slate-700 hover:border-islamic-green-600 dark:hover:border-islamic-green hover:text-islamic-green-600 dark:hover:text-islamic-green'
                        }`}
                    >
                        Kids
                    </button>
                    <button
                        onClick={() => setActiveTab('teens')}
                        className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-200 ${
                            activeTab === 'teens'
                                ? 'bg-islamic-green-600 text-white shadow-md hover:bg-islamic-green-700'
                                : 'bg-[#efefec] dark:bg-slate-800 text-islamic-dark dark:text-slate-300 border border-islamic-dark/20 dark:border-slate-700 hover:border-islamic-green-600 dark:hover:border-islamic-green hover:text-islamic-green-600 dark:hover:text-islamic-green'
                        }`}
                    >
                        Teens
                    </button>
                    <button
                        onClick={() => setActiveTab('adults')}
                        className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-200 ${
                            activeTab === 'adults'
                                ? 'bg-islamic-green-600 text-white shadow-md hover:bg-islamic-green-700'
                                : 'bg-[#efefec] dark:bg-slate-800 text-islamic-dark dark:text-slate-300 border border-islamic-dark/20 dark:border-slate-700 hover:border-islamic-green-600 dark:hover:border-islamic-green hover:text-islamic-green-600 dark:hover:text-islamic-green'
                        }`}
                    >
                        Adults
                    </button>
                </div>
            </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {loading ? (
                        <div className="col-span-full text-center py-12">
                            <p className="text-islamic-dark/70">{t('media.loading')}</p>
                        </div>
                    ) : videos.length === 0 ? (
                        <div className="col-span-full text-center py-12">
                            <p className="text-islamic-dark/70">{t('media.empty')}</p>
                        </div>
                    ) : videos.map((video) => (
                        <div key={video.id} className="islamic-card overflow-hidden hover:scale-[1.02] transition-transform">
                            <div className="aspect-video relative bg-islamic-dark/10 group cursor-pointer overflow-hidden rounded-t-lg" onClick={() => handleWatch(video)}>
                                {video.thumbnail_url ? (
                                    <img src={video.thumbnail_url} alt={video.title} className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                                ) : (
                                    <div className="flex items-center justify-center h-full text-islamic-dark/40">
                                        <PlayCircle size={48} />
                                    </div>
                                )}
                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                    <PlayCircle className="w-16 h-16 text-white" />
                                </div>
                                <div className="absolute bottom-2 right-2 bg-black/70 px-2 py-1 rounded text-xs text-white flex items-center gap-1">
                                    <Clock size={12} />
                                    {Math.floor((video.duration_seconds || 0) / 60)} min
                                </div>
                            </div>
                            <div className="p-6 space-y-3">
                                <div className="flex justify-between items-start gap-2">
                                    <h3 className="text-lg font-semibold text-islamic-dark line-clamp-2">{video.title}</h3>
                                    <Badge className="bg-islamic-gold/10 text-islamic-gold border-islamic-gold/20">{video.language}</Badge>
                                </div>
                                <p className="text-sm text-islamic-dark/70 line-clamp-2">{video.description}</p>
                                <Button className="w-full gap-2 btn-islamic" onClick={() => handleWatch(video)}>
                                    <PlayCircle size={16} /> {t('media.watch')}
                                </Button>
                            </div>
                        </div>
                    ))}
                </div>
            </section>
        </div>
    );
}

import React, { useState, useEffect, useRef } from 'react';
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Mic, MicOff, RefreshCw, AlertCircle, CheckCircle2, Play, Pause, Settings, ChevronRight, ChevronLeft } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Progress } from "@/components/ui/progress";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";
import { apiFetch } from '@/lib/api';
import { useLanguage } from '@/contexts/LanguageContext';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const Tarteel = () => {
  const { t } = useLanguage();
  const [isListening, setIsListening] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentAyah, setCurrentAyah] = useState(0);
  const [feedback, setFeedback] = useState<null | 'success' | 'error'>(null);
  const [audioLevel, setAudioLevel] = useState(0);
  const [mistakes, setMistakes] = useState<number[]>([]);
  const [transcription, setTranscription] = useState<string>("");
  
  // Data State
  type Verse = {
    id: number;
    text: string;
    translation: string;
    transliteration: string;
  };
  type Surah = {
    id: number;
    name: string;
    transliteration: string;
    translation: string;
    total_verses: number;
    verses: Verse[];
  };
  type SurahSummary = {
    id: number;
    name: string;
    transliteration: string;
    translation: string;
    totalVerses: number;
  };
  const [surahs, setSurahs] = useState<SurahSummary[]>([]);
  const [selectedSurahId, setSelectedSurahId] = useState<string>("78"); // Default to An-Naba
  const [currentSurahData, setCurrentSurahData] = useState<Surah | null>(null);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>();
  const { toast } = useToast();

  // Web Audio API refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  type RecognitionType = {
    lang: string;
    continuous: boolean;
    interimResults: boolean;
    start: () => void;
    stop: () => void;
    onresult: (event: RecognitionEvent) => void;
    onerror: (event: unknown) => void;
    onend: () => void;
  };
  type RecognitionEvent = {
    resultIndex: number;
    results: Array<{
      0: { transcript: string };
      isFinal: boolean;
      length: number;
    }>;
  };
  const recognitionRef = useRef<RecognitionType | null>(null);
  const [liveTranscript, setLiveTranscript] = useState<string>("");

  const normalizeArabic = (text: string) => {
    return text
      .replace(/[^\u0600-\u06FF\s]/g, "")
      .replace(/[\u064B-\u065F]/g, "")
      .replace(/[\u06D6-\u06ED]/g, "")
      .replace(/ٱ/g, "ا")
      .replace(/آ/g, "ا")
      .replace(/أ/g, "ا")
      .replace(/إ/g, "ا")
      .replace(/ى/g, "ي")
      .replace(/ة/g, "ه")
      .trim();
  };

  useEffect(() => {
    // Fetch Surah List
    apiFetch('/api/tarteel/surahs')
       .then(async res => {
         const data = await res.json();
         setSurahs(data);
       })
       .catch(err => {
         console.error("Failed to fetch surahs", err);
         toast({
           variant: "destructive",
           title: "Error",
           description: "Failed to load Surah list.",
         });
       });
  }, []);

  useEffect(() => {
    if (selectedSurahId) {
        setIsProcessing(true);
        apiFetch(`/api/tarteel/surahs/${selectedSurahId}`)
           .then(async res => {
               const data = await res.json();
               setCurrentSurahData(data);
               setCurrentAyah(0);
               setFeedback(null);
               setTranscription("");
           })
           .catch(err => {
               console.error("Failed to fetch surah details", err);
           })
           .finally(() => setIsProcessing(false));
    }
  }, [selectedSurahId]);

  useEffect(() => {
    return () => {
      stopListening();
    };
  }, []);

  const startListening = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaStreamRef.current = stream;
      
      const AudioContextCtor =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext!;
      const audioContext = new AudioContextCtor();
      audioContextRef.current = audioContext;
      
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;
      
      const source = audioContext.createMediaStreamSource(stream);
      source.connect(analyser);

      // Setup MediaRecorder
      const mediaRecorder = new MediaRecorder(stream, { mimeType: 'audio/webm' });
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.start(1000);
      
      // Real-time STT (Web Speech API) fallback
      type SRWindow = {
        SpeechRecognition?: new () => RecognitionType;
        webkitSpeechRecognition?: new () => RecognitionType;
      };
      const SpeechRecognition =
        (window as unknown as SRWindow).SpeechRecognition ||
        (window as unknown as SRWindow).webkitSpeechRecognition;
      if (SpeechRecognition) {
        const recognition = new SpeechRecognition() as RecognitionType;
        recognitionRef.current = recognition;
        recognition.lang = 'ar';
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.onresult = (event: RecognitionEvent) => {
          let interim = '';
          for (let i = event.resultIndex; i < event.results.length; i++) {
            const transcript = event.results[i][0].transcript;
            if (event.results[i].isFinal) {
              setLiveTranscript(prev => (prev ? `${prev} ${transcript}` : transcript));
            } else {
              interim += transcript;
            }
          }
          const currentText = (liveTranscript || interim).trim();
          setTranscription(currentText);
          if (currentSurahData) {
            const expected = currentSurahData.verses[currentAyah].text;
            const isOk = normalizeArabic(currentText).includes(normalizeArabic(expected));
            setFeedback(isOk ? 'success' : null);
          }
        };
        recognition.onerror = () => { setFeedback(null); };
        recognition.onend = () => {
          if (isListening) recognition.start();
        };
        recognition.start();
      }
      
      setIsListening(true);
      setFeedback(null);
      setMistakes([]);
      setTranscription("");
      visualize();
      
      toast({
        title: t('tarteel.listening_title'),
        description: t('tarteel.listening_desc'),
      });

    } catch (err) {
      console.error("Error accessing microphone:", err);
      toast({
        variant: "destructive",
        title: t('tarteel.mic_error_title'),
        description: t('tarteel.mic_error_desc'),
      });
    }
  };

  const stopListening = async () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
      
      // Wait for the stop event/data available
      await new Promise(resolve => {
        if (mediaRecorderRef.current) {
            mediaRecorderRef.current.onstop = resolve;
        } else {
            resolve(null);
        }
      });
    }
    
    if (recognitionRef.current) {
      try { recognitionRef.current.stop(); } catch (_e) { void 0; }
      recognitionRef.current = null;
    }

    if (mediaStreamRef.current) {
      mediaStreamRef.current.getTracks().forEach(track => track.stop());
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
    }
    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }
    
    setIsListening(false);
    setAudioLevel(0);
    
    if (chunksRef.current.length > 0) {
      processAudio();
    }
  };

  const processAudio = async () => {
    setIsProcessing(true);
    try {
      const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
      
      // Validate file size (10MB limit)
      if (blob.size > 10 * 1024 * 1024) {
        toast({
          variant: "destructive",
          title: t('tarteel.file_too_large_title'),
          description: t('tarteel.file_too_large_desc'),
        });
        setIsProcessing(false);
        return;
      }

      const formData = new FormData();
      formData.append('audio', blob, 'recitation.webm');
      if (currentSurahData) {
          formData.append('surahNumber', currentSurahData.id.toString());
          formData.append('ayahNumber', currentSurahData.verses[currentAyah].id.toString());
      } else {
          // Fallback or error
          console.error("No surah data loaded");
          setIsProcessing(false);
          return;
      }
      
      try {
        const response = await fetch(`${import.meta.env.VITE_API_URL || 'http://localhost:4000'}/api/tarteel/analyze`, {
          method: 'POST',
          body: formData, // No Content-Type header needed for FormData
        });

        if (!response.ok) {
          // Fallback to local comparison using live transcript
          if (currentSurahData && liveTranscript) {
            const expected = currentSurahData.verses[currentAyah].text;
            const isOk = normalizeArabic(liveTranscript).includes(normalizeArabic(expected));
            setTranscription(liveTranscript);
            setFeedback(isOk ? 'success' : 'error');
            if (isOk) {
              toast({ title: t('tarteel.success_title'), description: t('tarteel.success_desc'), className: "bg-primary text-primary-foreground border-none" });
            } else {
              setMistakes([currentAyah]);
              toast({ variant: "destructive", title: t('tarteel.correction_title'), description: `${t('tarteel.heard_label')} ${liveTranscript}` });
            }
            return;
          }
          throw new Error('Analysis failed');
        }

        const result = await response.json();
        
        setTranscription(result.transcription);
        
        if (result.isCorrect) {
          setFeedback('success');
          toast({
            title: t('tarteel.success_title'),
            description: t('tarteel.success_desc'),
            className: "bg-primary text-primary-foreground border-none",
          });
        } else {
          setFeedback('error');
          setMistakes([currentAyah]);
          toast({
            variant: "destructive",
            title: t('tarteel.correction_title'),
            description: `${t('tarteel.heard_label')} ${result.transcription}`,
          });
        }
      } catch (error) {
        console.error("API Error:", error);
        if (!liveTranscript) {
          toast({
            variant: "destructive",
            title: t('tarteel.api_error_title'),
            description: t('tarteel.api_error_desc'),
          });
        }
      } finally {
        setIsProcessing(false);
      }
    } catch (error) {
      console.error("Processing Error:", error);
      setIsProcessing(false);
    }
  };

  const visualize = () => {
    if (!analyserRef.current) return;
    
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    
    const draw = () => {
      if (!analyserRef.current) return;
      
      animationRef.current = requestAnimationFrame(draw);
      analyserRef.current.getByteFrequencyData(dataArray);
      
      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += dataArray[i];
      }
      const average = sum / bufferLength;
      setAudioLevel(average);
    };
    
    draw();
  };

  const nextAyah = () => {
    if (currentSurahData && currentAyah < currentSurahData.verses.length - 1) {
      setCurrentAyah(prev => prev + 1);
      setFeedback(null);
      setMistakes([]);
      setTranscription("");
    }
  };

  const prevAyah = () => {
    if (currentAyah > 0) {
      setCurrentAyah(prev => prev - 1);
      setFeedback(null);
      setMistakes([]);
      setTranscription("");
    }
  };

  return (
    <div className="container mx-auto p-6 max-w-4xl space-y-8 min-h-screen flex flex-col justify-center">
      <div className="text-center space-y-2">
        <h1 className="text-4xl font-bold text-gradient">{t('tarteel.title')}</h1>
      </div>

      <div className="flex justify-center">
          <Select value={selectedSurahId} onValueChange={setSelectedSurahId}>
            <SelectTrigger className="w-[280px]">
              <SelectValue placeholder={t('tarteel.select_surah')} />
            </SelectTrigger>
            <SelectContent>
              {surahs.map((surah) => (
                <SelectItem key={surah.id} value={surah.id.toString()}>
                  {surah.id}. {surah.name} ({surah.transliteration})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
      </div>

      <Card className="border-2 shadow-lg relative overflow-hidden backdrop-blur-sm bg-card/50">
        <div className="absolute top-0 left-0 w-full h-1 bg-hero-gradient" />
        
        <CardHeader className="flex flex-row items-center justify-between pb-2">
          <div className="flex items-center space-x-2 text-sm text-muted-foreground">
            <span className="font-semibold text-primary">{currentSurahData?.name} ({currentSurahData?.transliteration})</span>
            <span>•</span>
            <span>{t('tarteel.ayah_label')} {(currentSurahData?.verses[currentAyah]?.id) || currentAyah + 1}</span>
          </div>
          <Button variant="ghost" size="icon">
            <Settings className="h-5 w-5" />
          </Button>
        </CardHeader>

        <CardContent className="space-y-12 py-10">
          {/* Quran Text Display */}
          <div className="text-center space-y-8">
            {currentSurahData ? (
                <>
                <div 
                  className={cn(
                    "text-4xl md:text-5xl font-arabic leading-relaxed py-4 transition-colors duration-500",
                    isListening ? "text-primary" : "text-foreground",
                    feedback === 'error' && "text-destructive",
                    feedback === 'success' && "text-primary"
                  )}
                  dir="rtl"
                >
                  {currentSurahData.verses[currentAyah].text}
                </div>
                
                <p className="text-lg text-muted-foreground font-light">
                  {currentSurahData.verses[currentAyah].translation}
                </p>
                </>
            ) : (
                <div className="py-10">{t('tarteel.loading_surah')}</div>
            )}
            
            {transcription && feedback === 'error' && (
               <div className="mt-4 p-4 bg-destructive/10 rounded-lg border border-destructive">
                  <p className="text-sm text-muted-foreground mb-1">{t('tarteel.heard_label')}</p>
                  <p className="text-xl font-arabic text-destructive" dir="rtl">{transcription}</p>
               </div>
            )}
          </div>

          {/* Audio Visualizer */}
          <div className="h-24 flex items-center justify-center space-x-1">
            {isListening ? (
              Array.from({ length: 20 }).map((_, i) => (
                <div
                  key={i}
                  className="w-1 bg-primary rounded-full transition-all duration-75"
                  style={{
                    height: `${Math.max(4, Math.min(100, audioLevel * (Math.random() + 0.5)))}%`,
                    opacity: 0.8
                  }}
                />
              ))
            ) : (
              <div className="text-muted-foreground text-sm flex items-center space-x-2">
                {isProcessing ? (
                  <RefreshCw className="h-5 w-5 animate-spin" />
                ) : feedback === 'success' ? (
                  <CheckCircle2 className="h-8 w-8 text-primary" />
                ) : feedback === 'error' ? (
                  <AlertCircle className="h-8 w-8 text-destructive" />
                ) : (
                  <span>{t('tarteel.tap_mic')}</span>
                )}
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Controls */}
      <div className="flex items-center justify-center space-x-6">
        <Button 
          variant="outline" 
          size="icon" 
          onClick={prevAyah} 
          disabled={currentAyah === 0 || isListening}
          className="h-12 w-12 rounded-full"
        >
          <ChevronLeft className="h-6 w-6" />
        </Button>

        <Button
          size="lg"
          variant={isListening ? "destructive" : "default"}
          className={cn(
            "h-20 w-20 rounded-full shadow-xl transition-all duration-300 transform hover:scale-105",
            isListening && "animate-pulse ring-4 ring-red-500/20"
          )}
          onClick={isListening ? stopListening : startListening}
          disabled={isProcessing}
        >
          {isListening ? (
            <MicOff className="h-8 w-8" />
          ) : (
            <Mic className="h-8 w-8" />
          )}
        </Button>

        <Button 
          variant="outline" 
          size="icon" 
          onClick={nextAyah} 
          disabled={!currentSurahData || currentAyah === currentSurahData.verses.length - 1 || isListening}
          className="h-12 w-12 rounded-full"
        >
          <ChevronRight className="h-6 w-6" />
        </Button>
      </div>

      {/* Processing State */}
      {isProcessing && (
        <div className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center">
          <div className="bg-card p-6 rounded-lg shadow-lg flex flex-col items-center space-y-4 max-w-sm mx-4">
            <div className="relative">
              <div className="h-12 w-12 border-4 border-primary/30 border-t-primary rounded-full animate-spin" />
              <div className="absolute inset-0 flex items-center justify-center">
                <Mic className="h-5 w-5 text-primary" />
              </div>
            </div>
            <p className="text-lg font-medium">{t('tarteel.overlay_analyzing')}</p>
            <p className="text-sm text-muted-foreground text-center">
              {t('tarteel.overlay_checking')}
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Tarteel;
